    "tool-1b608afeb6fea0ee": {
      "name": "create_reminder",
      "description": "Create a durable reminder. Include time_interpretation for natural date/time wording so the backend can validate its meaning and calculate the due time. Its source_text must quote original user wording; use ACTIVE_DRAFT only for the displayed pending reminder. An ISO due_local alone cannot supply a missing date or AM/PM. recipient accepts me/spouse/husband/wife/both or the configured household names. An explicitly named assignee is a DM reminder regardless of where the command was typed unless the user explicitly asks for the group. destination=group sends one Family Shared claimable group reminder.",
      "parameters": {
        "type": "object",
        "properties": {
          "task": {
            "title": "Task",
            "type": "string"
          },
          "due_local": {
            "title": "Due Local",
            "type": "string"
          },
