            "type": "boolean"
          },
          "recipient": {
            "default": "me",
            "title": "Recipient",
            "type": "string"
          },
          "destination": {
            "default": "dm",
            "title": "Destination",
            "type": "string"
          },
          "claimable": {
            "default": false,
            "title": "Claimable",
            "type": "boolean"
          },
          "presence_aware": {
            "default": false,
            "title": "Presence Aware",
            "type": "boolean"
          },
          "delivery_class": {
            "default": "routine",
            "title": "Delivery Class",
            "type": "string"
          },
          "follow_up_after_hours": {
            "default": 24,
            "title": "Follow Up After Hours",
            "type": "integer"
          },
          "time_interpretation": {
            "anyOf": [
              {
                "additionalProperties": false,
                "properties": {
                  "source_text": {
                    "description": "Exact original user wording supporting this time; do not paraphrase this evidence.",
                    "maxLength": 240,
                    "minLength": 1,
                    "type": "string"
                  },
                  "kind": {
                    "enum": [
                      "RELATIVE",
                      "LOCAL_CLOCK"
                    ],
                    "type": "string"
                  },
                  "reference": {
                    "description": "ACTIVE_DRAFT only when answering the displayed pending reminder; CURRENT_MESSAGE for a separate new request.",
                    "enum": [
                      "CURRENT_MESSAGE",
                      "ACTIVE_DRAFT"
                    ],
                    "type": "string"
                  },
                  "relative_minutes": {
                    "description": "For RELATIVE: the user's stated delay, anchored to this message's receipt time.",
                    "maximum": 4320,
                    "minimum": 1,
                    "type": "integer"
